import{_ as a}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as i,o as t,af as s}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const b=JSON.parse('{"title":"Pi Agent 教程","description":"用官方 npm 或 install.sh 装上 Pi，在仓库里发出第一句。旧包不要当主路径。","frontmatter":{"title":"Pi Agent 教程","description":"用官方 npm 或 install.sh 装上 Pi，在仓库里发出第一句。旧包不要当主路径。","domain":"product","tags":["harness","coding-agent"],"role":"tutorial"},"headers":[],"relativePath":"zh/products/pi-agent/pi-agent.md","filePath":"zh/products/pi-agent/pi-agent.md","lastUpdated":1787110548000}'),n={name:"zh/products/pi-agent/pi-agent.md"};function o(r,e,l,p,d,h){return t(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="pi-agent-教程" tabindex="-1">Pi Agent 教程 <a class="header-anchor" href="#pi-agent-教程" aria-label="Permalink to &quot;Pi Agent 教程&quot;">​</a></h1><blockquote><p>官方文档：<a href="https://pi.dev/docs/latest/quickstart" target="_blank" rel="noreferrer">Quickstart</a>。本页只抄能打开的安装命令。</p></blockquote><h2 id="目标与非目标" tabindex="-1">目标与非目标 <a class="header-anchor" href="#目标与非目标" aria-label="Permalink to &quot;目标与非目标&quot;">​</a></h2><p><strong>你会完成：</strong> 装上现行包，跑 <code>pi</code>，知道四种模式和「默认没有什么」。</p><p><strong>不会做：</strong> 把 deprecated 包当主安装；把 OpenClaw 通道写进来。</p><h2 id="先决条件" tabindex="-1">先决条件 <a class="header-anchor" href="#先决条件" aria-label="Permalink to &quot;先决条件&quot;">​</a></h2><ul><li>Node.js（Quickstart 走 npm）。packages 页有的扩展写 <strong>Node &gt;= 22.19.0</strong>，本页不合成一个全站最低版本。 以你打开的那页为准。</li><li>一个模型供应商的 API key 或 OAuth（pi.dev：Authenticate via API keys or OAuth）。</li></ul><h2 id="_15-分钟内打开" tabindex="-1">15 分钟内打开 <a class="header-anchor" href="#_15-分钟内打开" aria-label="Permalink to &quot;15 分钟内打开&quot;">​</a></h2><h3 id="_1-装现行包" tabindex="-1">1. 装现行包 <a class="header-anchor" href="#_1-装现行包" aria-label="Permalink to &quot;1. 装现行包&quot;">​</a></h3><p><a href="https://pi.dev/docs/latest/quickstart" target="_blank" rel="noreferrer">Quickstart</a> 原文：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --ignore-scripts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @earendil-works/pi-coding-agent</span></span></code></pre></div><p><code>--ignore-scripts</code>：官方写明安装时关掉依赖生命周期脚本；Pi 正常 npm 安装不需要这些脚本。</p><p>Linux / macOS 还可：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://pi.dev/install.sh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> sh</span></span></code></pre></div><p><a href="https://pi.dev/news/2026/5/7/pi-has-a-new-home" target="_blank" rel="noreferrer">2026-05-07 公告</a>：主安装包改为 <code>@earendil-works/pi-coding-agent</code>，仓库从 <code>badlogic/pi-mono</code> 迁到 <code>earendil-works/pi</code>。不要再 <code>npm i -g @mariozechner/pi-coding-agent</code>。</p><h3 id="_2-发出第一句" tabindex="-1">2. 发出第一句 <a class="header-anchor" href="#_2-发出第一句" aria-label="Permalink to &quot;2. 发出第一句&quot;">​</a></h3><p>在真实仓库目录里：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pi</span></span></code></pre></div><p>进入 interactive TUI。脚本场景用官方的 print 模式：<code>pi -p &quot;query&quot;</code>；事件流加 <code>--mode json</code>（<a href="https://pi.dev/" target="_blank" rel="noreferrer">pi.dev</a>）。</p><p>切模型：官网写 <code>/model</code> 或 <code>Ctrl+L</code>；收藏夹 <code>Ctrl+P</code>。</p><h3 id="_3-项目说明放哪" tabindex="-1">3. 项目说明放哪 <a class="header-anchor" href="#_3-项目说明放哪" aria-label="Permalink to &quot;3. 项目说明放哪&quot;">​</a></h3><p>官网 Context engineering：</p><ul><li><strong><code>AGENTS.md</code></strong>：启动时从 <code>~/.pi/agent/</code>、父目录、当前目录加载。</li><li><strong><code>SYSTEM.md</code></strong>：按项目替换或追加默认系统提示。</li></ul><p>需要别人写好的能力：<code>pi install npm:@foo/pi-tools</code> 或 <code>pi install git:github.com/badlogic/pi-doom</code>（pi.dev 示例，原样抄）。</p><h2 id="默认没有什么" tabindex="-1">默认没有什么 <a class="header-anchor" href="#默认没有什么" aria-label="Permalink to &quot;默认没有什么&quot;">​</a></h2><p>来自 <a href="https://pi.dev/" target="_blank" rel="noreferrer">pi.dev</a> 与 <a href="https://github.com/earendil-works/pi" target="_blank" rel="noreferrer">README</a>：</p><ul><li>没有内置 sub-agents、plan mode。</li><li>没有内置 MCP（可用 skill / extension）。</li><li>没有内置权限系统；要隔离去官方 containerization 文档。</li></ul><p>这些是设计，不是漏写的开关。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="./pi-agent-cheatsheet.html">速查</a></li><li><a href="./pi-agent-glossary.html">术语</a></li><li>接到聊天通道 → <a href="/zh/products/openclaw/">OpenClaw</a></li></ul>',30)])])}const m=a(n,[["render",o]]);export{b as __pageData,m as default};
